import sys,json,urllib.request
sys.path.insert(0,'E:/Neur0StoreCurator')
import register
before,after,p,already=register.planned()
if not already or len(before)!=7 or len(after)!=7:raise RuntimeError('registration_not_persisted')
others=[r for r in before if r.get('id')!='tg-curator-owner']
if len(others)!=6:raise RuntimeError('original_agent_count_changed')
cur=[r for r in before if r.get('id')=='tg-curator-owner']
if len(cur)!=1 or cur[0].get('url')!=register.CURATOR_URL or cur[0].get('profileId')!=p.get('id'):raise RuntimeError('curator_mismatch')
try:
 with urllib.request.urlopen('http://127.0.0.1:17448/api/supervisor-watchdog?detect=0',timeout=5) as f:s=json.load(f)
 watchdog={'mode':s.get('config',{}).get('mode'),'allowAutonomousSend':s.get('config',{}).get('allowAutonomousSend')}
except Exception as e:watchdog={'read_error':type(e).__name__}
print(json.dumps({'registered':already,'total':len(before),'original_agents':len(others),'curator_id':cur[0]['id'],'profile_port':p.get('debugPort'),'watchdog':watchdog},ensure_ascii=True))
